examples.code:
#include <iostream>
#include <string>

int main() {
    std::string a = "AAA";
    std::string b = "BBBB";

    std::cout << "Before swap:\n"
                 "a = "
              << a
              << "\n"
                 "b = "
              << b << "\n\n";

    std::swap(a, b);

    std::cout << "After swap:\n"
                 "a = "
              << a
              << "\n"
                 "b = "
              << b << '\n';
}
